class Solution {
    private int bit(char value){
        return value=='a'?1:value=='e'?2:value=='i'?4:value=='o'?8:value=='u'?16:0;
    }
    public int countVowelSubstrings(String word){
        int answer=0;
        for(int left=0;left<word.length();left++){
            int mask=0;
            for(int right=left;right<word.length();right++){
                int value=bit(word.charAt(right));
                if(value==0)break;
                mask|=value;
                if(mask==31)answer++;
            }
        }
        return answer;
    }
}

code.kotlin:
class Solution {
    private fun bit(value:Char)=when(value){
        'a'->1;
        'e'->2;
        'i'->4;
        'o'->8;
        'u'->16;
        else->0
    };
    fun countVowelSubstrings(word:String):Int{
        var answer=0;
        for(left in word.indices){
            var mask=0;
            for(right in left until word.length){
                val value=bit(word[right]);
                if(value==0)break;
                mask=mask or value;
                if(mask==31)answer++
            }
        };
        return answer
    }
}

